import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.Ddyno5UB.js";const g=JSON.parse('{"title":"Builds and Deployments","description":"","frontmatter":{},"headers":[],"relativePath":"openshift/5-builds-and-deployments.md","filePath":"openshift/5-builds-and-deployments.md"}'),n={name:"openshift/5-builds-and-deployments.md"};function l(o,s,p,r,d,h){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="builds-and-deployments" tabindex="-1">Builds and Deployments <a class="header-anchor" href="#builds-and-deployments" aria-label="Permalink to &quot;Builds and Deployments&quot;">​</a></h1><p>Unlike Vanilla Kubernetes which expects you to build your container images externally (using Docker/Podman, Jenkins, or GitHub Actions) and push them to a registry, <strong>OpenShift can build source code into container images directly inside the cluster.</strong></p><h2 id="imagestreams-is" tabindex="-1">ImageStreams (IS) <a class="header-anchor" href="#imagestreams-is" aria-label="Permalink to &quot;ImageStreams (IS)&quot;">​</a></h2><p>An <strong>ImageStream</strong> does not contain actual image data. Instead, it is a pointer or alias to a container image located in the internal OpenShift registry or an external registry (like Docker Hub).</p><p>ImageStreams provide powerful abstraction. If you tell your deployment to watch an ImageStream, OpenShift can automatically trigger a rolling update the moment a new image is pushed to that stream.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List all ImageStreams in the project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is</span></span></code></pre></div><h2 id="buildconfigs-bc" tabindex="-1">BuildConfigs (BC) <a class="header-anchor" href="#buildconfigs-bc" aria-label="Permalink to &quot;BuildConfigs (BC)&quot;">​</a></h2><p>A <strong>BuildConfig</strong> defines the process of transforming source code into a runnable container image.</p><p>The most powerful build strategy in OpenShift is <strong>S2I (Source-to-Image)</strong>. S2I takes your raw application source code (e.g., a Python Flask app), injects it into a &quot;builder image&quot;, compiles it, and outputs a final, ready-to-run container image into an ImageStream.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start a build manually from an existing BuildConfig</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start-build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app-build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Watch the build logs stream in real-time</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bc/my-app-build</span></span></code></pre></div><p>BuildConfigs can be triggered automatically via Webhooks (e.g., every time a developer merges code into the <code>main</code> branch on GitHub, GitHub pings OpenShift, which starts a new build).</p><h2 id="deploymentconfigs-dc-vs-deployments" tabindex="-1">DeploymentConfigs (DC) vs Deployments <a class="header-anchor" href="#deploymentconfigs-dc-vs-deployments" aria-label="Permalink to &quot;DeploymentConfigs (DC) vs Deployments&quot;">​</a></h2><p>When reading older OpenShift tutorials, you will heavily see <code>DeploymentConfig</code> (DC).</p><p>A <code>DeploymentConfig</code> is an OpenShift-specific resource that predates the standard K8s <code>Deployment</code>. DCs were tightly integrated with ImageStreams to trigger automatic rollouts when new images were built.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>DeploymentConfigs are deprecated in modern OpenShift (OCP 4.x+).</strong> You should use standard Kubernetes <code>Deployment</code> objects for all modern workloads.</p></div><p>Standard K8s <code>Deployments</code> have fully caught up in functionality and are the industry standard. OpenShift now natively supports triggering K8s Deployments via ImageStream changes.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Scale a standard deployment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scale</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --replicas=3</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View the rollout history</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> history</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/my-app</span></span></code></pre></div>`,17)])])}const u=e(n,[["render",l]]);export{g as __pageData,u as default};
